INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-imc', 'Calculadora de IMC (Índice de Masa Corporal)', 'El IMC (Índice de Masa Corporal) se calcula con la fórmula peso (kg) dividido altura (m) al cuadrado. La OMS clasifica los resultados así: menos de 18,5 bajo peso; entre 18,5 y 24,9 peso normal; entre 25 y 29,9 sobrepeso; 30 a 34,9 obesidad grado I; 35 a 39,9 grado II; y 40 o más grado III. Por ejemplo, 70 kg con 1,70…', 'salud', 'https://hacecuentas.com/calculadora-imc', 1);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-actualizacion-alquiler-icl', 'Calculadora Actualización de Alquiler por ICL (BCRA)', 'El ICL (Índice de Contratos de Locación) del BCRA combina 50 % IPC + 50 % RIPTE y se publica diariamente. El nuevo alquiler se calcula multiplicando el alquiler actual por el coeficiente ICL (ICL del día de actualización dividido por ICL del día de firma del contrato). Aplica a contratos Ley 27.551 y los que pactaron…', 'finanzas', 'https://hacecuentas.com/calculadora-actualizacion-alquiler-icl', 2);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-indemnizacion-despido', 'Calculadora de indemnización por despido sin causa', 'La indemnización por despido sin causa se calcula con la mejor remuneración bruta del último año multiplicada por los años de antigüedad (art. 245 LCT). A eso se suman preaviso (15 días a 2 meses según antigüedad), integración del mes, SAC proporcional y vacaciones no gozadas. La fracción mayor a 3 meses cuenta como…', 'finanzas', 'https://hacecuentas.com/calculadora-indemnizacion-despido', 3);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('dias-entre-dos-fechas', 'Calculadora de días entre dos fechas', 'Para calcular los días entre dos fechas, restá la fecha final menos la inicial: el resultado es la diferencia en días corridos. Los días hábiles excluyen sábados y domingos (aprox 21-23 por mes). Por ejemplo, del 1 de enero al 14 de abril de 2026 hay 103 días corridos o 74 días hábiles. El cálculo contempla años…', 'vida', 'https://hacecuentas.com/dias-entre-dos-fechas', 4);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-aguinaldo-sac', 'Calculadora de Aguinaldo (SAC)', 'El aguinaldo (SAC) en Argentina equivale al 50% de la mejor remuneración bruta del semestre, proporcional a los meses trabajados. Se paga antes del 30 de junio y antes del 18 de diciembre. Le descuentan 17% de aportes (jubilación 11% + obra social 3% + PAMI 3%). Si tu mejor sueldo del semestre fue $1.500.000, el SAC…', 'finanzas', 'https://hacecuentas.com/calculadora-aguinaldo-sac', 5);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-liquidacion-final-renuncia', 'Calculadora de Liquidación Final por Renuncia', 'Cuando renunciás a tu trabajo, tu empleador debe pagarte una liquidación final que incluye: días trabajados del mes, vacaciones no gozadas, SAC proporcional sobre vacaciones y SAC proporcional del semestre. Esta calculadora te muestra el desglose completo de lo que te corresponde cobrar.', 'finanzas', 'https://hacecuentas.com/calculadora-liquidacion-final-renuncia', 6);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-edad-exacta', 'Calculadora de edad', 'Para calcular tu edad exacta, restá la fecha de hoy a tu fecha de nacimiento y desglosá el resultado en años, meses y días. La calc contempla años bisiestos automáticamente. Alguien nacido el 15 de marzo de 1990 al 26 de mayo de 2026 tiene 36 años, 2 meses y 11 días, equivalente a 13.221 días o unas 317.300 horas…', 'vida', 'https://hacecuentas.com/calculadora-edad-exacta', 7);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-indice-masa-corporal-pediatrico', 'Calculadora de IMC pediátrico con percentil', 'Para calcular el IMC pediátrico dividí el peso en kg por la altura en metros al cuadrado: IMC = peso ÷ (altura)². En niños no se interpreta con los rangos de adultos sino con el percentil de IMC para edad y sexo según tablas CDC 2000 u OMS: percentil <5 es bajo peso, 5 a <85 normal, 85 a <95 sobrepeso, ≥95 obesidad…', 'salud', 'https://hacecuentas.com/calculadora-indice-masa-corporal-pediatrico', 8);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-embarazo', 'Calculadora de embarazo', 'Para saber en qué semana de embarazo estás, contá los días desde el primer día de tu última menstruación (FUM) y dividilos por 7. El embarazo dura 40 semanas (280 días) contadas desde la FUM —no desde la concepción, que ocurre ~2 semanas después—, y la fecha probable de parto es FUM + 280 días. Cada semana el bebé…', 'salud', 'https://hacecuentas.com/calculadora-embarazo', 9);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-impuesto-ganancias-sueldo', 'Calculadora de Impuesto a las Ganancias — Sueldo (relación de dependencia)', 'Si trabajás en relación de dependencia en Argentina y tu sueldo bruto supera el Mínimo No Imponible (MNI), tu empleador te retiene mensualmente el Impuesto a las Ganancias de 4ta categoría y lo transfiere a ARCA (ex AFIP) en tu nombre.', 'finanzas', 'https://hacecuentas.com/calculadora-impuesto-ganancias-sueldo', 10);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-actualizacion-inflacion-ipc', 'Calculadora de actualización por inflación (IPC)', 'Para actualizar un monto por inflación IPC argentina, multiplicá el valor original por (1 + inflación acumulada / 100). Por ejemplo, con un IPC acumulado del 30% en el período, $200.000 equivalen a $260.000 actualizados. La fuente oficial es el INDEC, que publica el IPC mensual y acumulado el tercer martes de cada…', 'finanzas', 'https://hacecuentas.com/calculadora-actualizacion-inflacion-ipc', 11);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-sexo-bebe-tabla-china', 'Calculadora de sexo del bebé (tabla china)', 'La tabla china de predicción del sexo es un método popular (y divertido) que supuestamente predice si tu bebé será nene o nena basándose en la edad lunar de la madre al momento de la concepción y el mes lunar de concepción.', 'salud', 'https://hacecuentas.com/calculadora-sexo-bebe-tabla-china', 12);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('conversor-moneda-dolar-peso-real-latam', 'Conversor de monedas de Latinoamerica', 'Conversor rapido de monedas de Latinoamerica y el dolar estadounidense. Converti entre 9 monedas: dolar (USD), peso argentino (ARS), peso mexicano (MXN), peso colombiano (COP), peso chileno (CLP), real brasileno (BRL), peso uruguayo (UYU), sol peruano (PEN) y boliviano (BOB).', 'finanzas', 'https://hacecuentas.com/conversor-moneda-dolar-peso-real-latam', 13);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-costo-m2-construccion-argentina', 'Costo de construcción por m² (Argentina)', 'En Argentina 2026 el metro cuadrado de construcción va de USD 600 (vivienda económica) a USD 2800 (premium). Una casa estándar urbana en GBA ronda USD 900 por metro, en CABA sube 25 por ciento y en el interior baja 15 por ciento. Construir 100 metros sale entre USD 90.000 y USD 180.000 sin terreno. Los materiales son…', 'construccion', 'https://hacecuentas.com/calculadora-costo-m2-construccion-argentina', 14);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-art-indemnizacion-tabla-incapacidad-laboral-permanente', 'Calculadora de indemnización ART por Incapacidad Laboral Permanente Parcial Definitiva', 'La indemnización por Incapacidad Laboral Permanente Parcial Definitiva (ILPPD) está regulada por los Artículos 14 y 15 de la Ley de Riesgos del Trabajo 24.557 (modificada por las Leyes 26.773 y 27.348).', 'finanzas', 'https://hacecuentas.com/calculadora-art-indemnizacion-tabla-incapacidad-laboral-permanente', 15);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-porcentajes', 'Calculadora de porcentajes', 'El porcentaje (del latín per centum, ''por cada cien'') es una de las operaciones matemáticas más usadas en la vida diaria: calcular descuentos, aumentos de sueldo, propinas, comisiones, inflación, variación de precios, impuestos.', 'vida', 'https://hacecuentas.com/calculadora-porcentajes', 16);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-edad-en-semanas', 'Calculadora de tu edad exacta en semanas, días y horas', 'Para calcular tu edad en semanas, restá la fecha de nacimiento a la fecha de hoy y dividí el total de días por 7. Un año equivale a unas 52,18 semanas. A los 30 años llevás unas 1.565 semanas vividas (15.700 días, 376.800 horas); a los 50, unas 2.609 semanas; a los 80, unas 4.174. La calc ajusta automáticamente los…', 'vida', 'https://hacecuentas.com/calculadora-edad-en-semanas', 17);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-transfer-auto-costo-registro', 'Calculadora Costo de Transferencia de Auto', 'El costo de transferencia de un auto en Argentina depende de su valuación fiscal e incluye arancel del Registro Automotor (~1,5 %), sellado provincial (0,5 %-2 %) y verificación policial. En 2026, una transferencia típica cuesta entre $200.000 y $500.000. Usá la calculadora para estimar tu caso.', 'automotor', 'https://hacecuentas.com/calculadora-transfer-auto-costo-registro', 18);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-ovulacion-dias-fertiles', 'Calculadora de ovulación', 'Para calcular tu día de ovulación, restá 14 días al largo de tu ciclo y sumalos a la fecha de tu última menstruación. Con un ciclo de 28 días y FUM el 1 de junio, ovulás el 15 de junio. La ventana fértil son los 5 días previos a la ovulación más el día en sí, porque los espermatozoides sobreviven hasta 5 días…', 'salud', 'https://hacecuentas.com/calculadora-ovulacion-dias-fertiles', 19);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-imc-infantil-percentil', 'Calculadora de IMC infantil con percentiles OMS', 'Cuando el pediatra dice que tu hijo está en el "percentil 75 de IMC", ¿sabés qué significa? El <strongIMC infantil</strong no se lee igual que en adultos: un mismo número puede ser completamente normal en una nena de 6 años y preocupante en un varón de 14. Por eso existe el sistema de percentiles.', 'salud', 'https://hacecuentas.com/calculadora-imc-infantil-percentil', 20);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-millas-avianca-lifemiles', 'Millas Avianca LifeMiles por destino', 'Las millas Avianca LifeMiles usan una tabla de premios fija y valen alrededor de 1,6 centavos de dólar cada una. Un pasaje economy ida y vuelta arranca en 14.000 millas para destinos cercanos y llega a 120.000 para los lejanos. Por ejemplo, Bogotá en economy ida cuesta unas 7.500 millas más impuestos. En business se…', 'viajes', 'https://hacecuentas.com/calculadora-millas-avianca-lifemiles', 21);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-feriados-argentina-2026-calendario', 'Feriados Argentina 2026: calendario completo', 'Consulta el calendario completo de feriados nacionales de Argentina 2026: feriados inamovibles, trasladables, dias no laborables y puentes turisticos. Filtra por mes o por tipo de feriado, y enterate al instante cual es el proximo feriado y cuantos dias faltan. Datos basados en la legislacion argentina vigente (Ley…', 'vida', 'https://hacecuentas.com/calculadora-feriados-argentina-2026-calendario', 22);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-dias-vacaciones-ley', 'Calculadora de Días de Vacaciones según Antigüedad', 'En Argentina los días de vacaciones por ley dependen de la antigüedad al 31 de diciembre, según el artículo 150 de la LCT: hasta 5 años corresponden 14 días corridos; de 5 a 10 años, 21 días; de 10 a 20 años, 28 días; y con más de 20 años, 35 días. Incluyen los fines de semana.', 'vida', 'https://hacecuentas.com/calculadora-dias-vacaciones-ley', 23);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-sueldo-neto-a-bruto', 'Calculadora de sueldo neto a bruto en Argentina', 'Cuando te ofrecen un trabajo "en mano" (neto), comparás dos ofertas una con bruto y otra con neto, o negociás un aumento sobre lo que cobrás efectivamente, necesitás hacer el camino inverso al habitual: desde el neto despejar el bruto.', 'finanzas', 'https://hacecuentas.com/calculadora-sueldo-neto-a-bruto', 24);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-conversor-metros-lineales-a-metros-cuadrados', 'Conversor de metros lineales a metros cuadrados', 'Para pasar metros lineales a metros cuadrados, multiplicá los metros lineales por el ancho del material en metros: m² = m lineales × ancho. Para volver al revés, dividí los m² por el ancho. Ejemplo: comprás 6 metros lineales de tela de 1,40 m de ancho, eso da 6 × 1,40 = 8,4 m². Sumá siempre 10% extra por cortes y…', 'construccion', 'https://hacecuentas.com/calculadora-conversor-metros-lineales-a-metros-cuadrados', 25);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-interes-judicial-tasa', 'Calculadora de Interés Judicial (Tasa Activa BNA)', 'Los intereses judiciales en Argentina se calculan habitualmente con la tasa activa BNA a 30 días (33-38% TNA en 2026). Fórmula de interés simple: Capital × (tasa anual / 365) × días desde la mora. Ejemplo: $5.000.000 al 75% anual durante 365 días generan $3.750.000 de intereses. La tasa varía por fuero…', 'finanzas', 'https://hacecuentas.com/calculadora-interes-judicial-tasa', 26);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('conversor-pulgadas-centimetros-metros', 'Conversor de Pulgadas a Centímetros y Pies a Metros', 'Convertir entre pulgadas y centímetros, o entre pies y metros, es una necesidad frecuente: al comprar un televisor (las pantallas se miden en pulgadas), elegir ropa en talle americano, interpretar planos de construcción, o leer especificaciones técnicas de productos importados.', 'vida', 'https://hacecuentas.com/conversor-pulgadas-centimetros-metros', 27);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-interes-compuesto', 'Calculadora de interés compuesto', 'El interés compuesto se calcula con la fórmula M = C × (1 + i)ⁿ, donde C es el capital inicial, i la tasa de interés por período y n la cantidad de períodos. A diferencia del interés simple, los intereses generados se reinvierten y producen nuevos intereses, haciendo que el capital crezca de forma exponencial.', 'finanzas', 'https://hacecuentas.com/calculadora-interes-compuesto', 28);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-costo-impresion-3d-pieza', 'Calculadora de costo de impresión 3D por pieza', 'El costo real de una impresión 3D no es solo el filamento: hay que sumar electricidad (80-250 W según modelo), desgaste (correas, rulemanes, hotend, boquillas, PEI) y tu tiempo. Esta calculadora toma los 5 componentes críticos del costo (gramos, precio/kg, horas, watts, $/kWh y margen) y devuelve el precio final por…', 'tecnologia', 'https://hacecuentas.com/calculadora-costo-impresion-3d-pieza', 29);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-combustible-viaje-auto', 'Calculadora de combustible para un viaje', 'Para calcular el combustible de un viaje en auto multiplicá los kilómetros totales por el consumo del vehículo (en litros cada 100 km) y dividilo por 100. Multiplicando los litros resultantes por el precio del combustible obtenés el costo total. Un auto naftero promedio consume 7-10 L/100 km en ruta, un diésel 5-7 y…', 'viajes', 'https://hacecuentas.com/calculadora-combustible-viaje-auto', 30);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('sueldo-en-mano-argentina', 'Calculadora de sueldo en mano (Argentina)', 'Del sueldo bruto al neto en Argentina se descuenta el 17% de aportes (11% jubilación SIPA, 3% obra social y 3% PAMI), pero sobre una base con tope: hasta 4.414.652 pesos mensuales (junio 2026, Ley 24.241). Por encima de ese bruto los aportes se congelan, así que en sueldos altos el descuento efectivo baja del 17%. Si…', 'finanzas', 'https://hacecuentas.com/sueldo-en-mano-argentina', 31);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-conversor-fahrenheit-a-celsius-horno', 'Conversor de grados Fahrenheit a grados Celsius', 'Para convertir °F a °C en recetas de horno: °C = (°F - 32) × 5/9. Valores típicos: 350°F = 177°C, 400°F = 204°C, 450°F = 232°C. Las recetas americanas usan Fahrenheit.', 'cocina', 'https://hacecuentas.com/calculadora-conversor-fahrenheit-a-celsius-horno', 32);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-antiguedad-laboral', 'Calculadora de Antigüedad Laboral', 'La antigüedad laboral determina derechos clave como la cantidad de días de vacaciones, el monto de indemnización por despido, el plus por antigüedad y las licencias. Esta calculadora te dice exactamente cuántos años, meses y días llevás en tu empleo desde la fecha de ingreso.', 'vida', 'https://hacecuentas.com/calculadora-antiguedad-laboral', 33);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-gastos-escritura-compra-inmueble', 'Calculadora de gastos de escrituración de inmueble', 'Comprar un inmueble implica gastos de escrituración que representan entre el 5% y el 8% del valor de la propiedad: honorarios del escribano, impuesto de sellos, inscripción en el Registro de la Propiedad y certificados. El ITI (1,5%) fue derogado en 2024 por la Ley 27.743: las personas humanas ya no lo pagan al…', 'finanzas', 'https://hacecuentas.com/calculadora-gastos-escritura-compra-inmueble', 34);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-iva-incluido-neto-discriminar', 'Calculadora de IVA — incluido, neto y discriminado', '¿Necesitás sacar el IVA de un precio final o agregar IVA a un precio neto? Esta calculadora hace ambas operaciones al instante con las tres alícuotas de IVA argentinas: 10.5% (productos de la canasta básica, transporte), 21% (alícuota general) y 27% (telecomunicaciones, energía a comercios).', 'finanzas', 'https://hacecuentas.com/calculadora-iva-incluido-neto-discriminar', 35);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-fondo-desempleo-anses-monto-tiempo', 'Fondo desempleo ANSES', 'Esta calculadora te da el cálculo de fondo desempleo ANSES según sueldo promedio 6 meses previos $ y meses aportados últimos 3 años. Devuelve monto mensual junto con contexto para interpretar el valor. Los valores de referencia se revisan periódicamente contra las fuentes oficiales citadas al pie.', 'finanzas', 'https://hacecuentas.com/calculadora-fondo-desempleo-anses-monto-tiempo', 36);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-vacaciones-argentina', 'Calculadora de vacaciones proporcionales y plus vacacional', 'El plus vacacional en Argentina se calcula dividiendo el sueldo bruto por 25 y multiplicando por los días corridos que te corresponden según antigüedad (art. 155 LCT). Con menos de 5 años tenés 14 días corridos; entre 5 y 10, 21 días. Si trabajaste menos de un año, corresponden días proporcionales a los meses…', 'finanzas', 'https://hacecuentas.com/calculadora-vacaciones-argentina', 37);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-plazo-fijo', 'Calculadora de plazo fijo', 'Para calcular un plazo fijo en Argentina multiplicá el capital por la TNA del banco y por los días dividido 365. Con 1.000.000 de pesos a TNA 38% por 30 días se ganan 31.233 pesos de intereses y se reciben 1.031.233 al vencimiento. Las personas humanas no pagan Ganancias sobre intereses de plazo fijo en pesos y los…', 'finanzas', 'https://hacecuentas.com/calculadora-plazo-fijo', 38);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-filtrado-glomerular-tfg-creatinina', 'Calculadora de filtrado glomerular (eGFR) por creatinina', 'El filtrado glomerular estimado (eGFR) mide la función renal a partir de la creatinina con la fórmula CKD-EPI 2021. Un valor de 90 o más es normal; entre 60 y 89 hay disminución leve; entre 30 y 59, enfermedad renal crónica moderada; bajo 30 es severa y bajo 15 indica diálisis. Por ejemplo, 58,8 corresponde al estadio…', 'salud', 'https://hacecuentas.com/calculadora-filtrado-glomerular-tfg-creatinina', 39);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-fecha-probable-parto', 'Calculadora de fecha probable de parto', 'La fecha probable de parto (FPP) se estima sumando 280 días (40 semanas) al primer día de la última menstruación, según la Regla de Naegele. El método más preciso es la ecografía del primer trimestre (semanas 7-12), que data el embarazo midiendo la longitud cráneo-cola (CRL) con error de ±5 días, frente a ±14 días de…', 'salud', 'https://hacecuentas.com/calculadora-fecha-probable-parto', 40);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-sueldo-neto-chile-2026', 'Calculadora de Sueldo Líquido Chile 2026', 'En Chile, el sueldo líquido (neto) es lo que te queda después de los descuentos obligatorios: AFP (cotización + comisión), salud (Fonasa 7% o Isapre), Seguro de Cesantía (0.6%) e Impuesto Único de Segunda Categoría (progresivo). Las comisiones de las AFP varían: desde un 0.49% (AFP Uno) hasta 1.45% (AFP ProVida).', 'finanzas', 'https://hacecuentas.com/calculadora-sueldo-neto-chile-2026', 41);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-cuota-alimentaria-estimacion', 'Calculadora de cuota alimentaria (estimación)', 'La cuota alimentaria en Argentina no tiene porcentaje fijo por ley: la jurisprudencia maneja un rango del 20-30% del ingreso neto del obligado por 1 hijo, 30-40% por 2 hijos y 40-50% por 3 o más. El juez define el monto final según necesidades del niño y capacidad económica del obligado.', 'finanzas', 'https://hacecuentas.com/calculadora-cuota-alimentaria-estimacion', 42);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-calorias-diarias-tdee', 'Calculadora de calorías diarias (TDEE)', 'El TDEE (Total Daily Energy Expenditure) o Gasto Energético Diario Total es la cantidad de calorías que tu cuerpo consume en un día entero: el metabolismo basal (lo que gastás respirando, digiriendo y en reposo) más la actividad física y el efecto térmico de los alimentos.', 'salud', 'https://hacecuentas.com/calculadora-calorias-diarias-tdee', 43);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-edad-perro-anos-humanos', 'Edad de tu perro en años humanos (fórmula AVMA con tamaño)', 'La regla clásica de multiplicar por 7 la edad del perro para pasarla a años humanos es incorrecta — fue una heurística de los años 50 sin base científica.', 'mascotas', 'https://hacecuentas.com/calculadora-edad-perro-anos-humanos', 44);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-patente-auto-provincia', 'Calculadora Patente Automotor por Provincia', 'La patente automotor en Argentina se calcula multiplicando la valuación fiscal del vehículo (DNRPA) por la alícuota provincial, que va del 1,8 al 3,5 por ciento. CABA cobra 3,5, Buenos Aires 3, Córdoba 3,2 y Tierra del Fuego solo 1,8. Un auto valuado en 15 millones de pesos en PBA paga 525.000 pesos anuales en 5 o 6…', 'automotor', 'https://hacecuentas.com/calculadora-patente-auto-provincia', 45);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-peso-ideal', 'Calculadora de peso ideal según altura y sexo', 'No existe un único ''peso ideal'': depende de tu contextura ósea, composición corporal (grasa vs músculo), edad y genética. Esta calculadora te da las tres fórmulas más usadas en medicina: Devine (1974) —la más extendida en farmacología para dosificar medicamentos—, Robinson (1983) —refinamiento más conservador— y…', 'salud', 'https://hacecuentas.com/calculadora-peso-ideal', 46);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-impuesto-renta-colombia-persona-natural-2026', 'Impuesto de Renta Colombia Persona Natural 2026', 'Para calcular el impuesto de renta persona natural Colombia 2026: 1) Sumá ingresos anuales. 2) Restá ingresos no constitutivos + deducciones (hasta 40% del ingreso, tope 1.340 UVT) + rentas exentas (25% renta laboral según Art. 206 ET). 3) Convertí la renta gravable a UVT dividiendo por $52.374 (UVT 2026 oficial, Res…', 'finanzas', 'https://hacecuentas.com/calculadora-impuesto-renta-colombia-persona-natural-2026', 47);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-costo-peaje-ruta', 'Calculadora de Costo de Peajes por Ruta', 'Para calcular el costo de peajes en una ruta argentina multiplicá la cantidad de cabinas del trayecto por el precio promedio según tu categoría de vehículo y duplicalo si es ida y vuelta. Un auto a Mar del Plata por Autovía 2 paga aproximadamente $12.500 por sentido (5 cabinas), $25.000 ida y vuelta. Con Telepase…', 'automotor', 'https://hacecuentas.com/calculadora-costo-peaje-ruta', 48);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-siembra-calendario-argentina-zona', 'Calendario de siembra en Argentina: qué sembrar según zona y mes', 'Argentina tiene 6 zonas climáticas principales para huerta: desde la Patagonia fría hasta el Norte subtropical. Lo que se siembra en Buenos Aires en septiembre no es lo mismo que en Mendoza o en Tucumán.', 'jardineria', 'https://hacecuentas.com/calculadora-siembra-calendario-argentina-zona', 49);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-carne-asado-kg-por-persona', 'Calculadora de carne para asado por persona', 'La pregunta eterna del asador argentino: ¿cuánta carne compro? Comprar de más es desperdicio (y caro), comprar de menos es un pecado social. Esta calculadora te dice los kilos exactos de carne, achuras y embutidos según la cantidad de comensales, el tipo de evento y si hay entrada previa.', 'cocina', 'https://hacecuentas.com/calculadora-carne-asado-kg-por-persona', 50);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-cuota-alimentaria-hijos', 'Calculadora de Cuota Alimentaria para Hijos', 'La cuota alimentaria es la obligación económica que tiene el progenitor no conviviente para cubrir las necesidades de sus hijos (alimentación, educación, salud, vivienda, vestimenta y esparcimiento). Esta calculadora estima un rango orientativo basado en los criterios judiciales más comunes en Argentina.', 'vida', 'https://hacecuentas.com/calculadora-cuota-alimentaria-hijos', 51);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-horas-extra', 'Calculadora de horas extra (recargo 50% y 100%)', 'Hora extra al 50% = (sueldo/200) × 1,5 (días hábiles y sábado hasta 13hs). Hora extra al 100% = (sueldo/200) × 2 (sábado tarde, domingo y feriados). Están exentas de Ganancias (Art. 81 bis Ley 20.628).', 'finanzas', 'https://hacecuentas.com/calculadora-horas-extra', 52);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-monotributo-2026', 'Calculadora de monotributo 2026', 'En 2026 la cuota del monotributo va desde $42.387/mes en la categoría A (facturación anual hasta $10.277.988) hasta $1.381.688/mes en la K para servicios o $600.880 para venta de bienes (tope $108.357.084). Ingresá tu facturación anual y la actividad: la calculadora te dice tu categoría, la cuota mensual y el margen…', 'finanzas', 'https://hacecuentas.com/calculadora-monotributo-2026', 53);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-semanas-embarazo', 'Calculadora de semanas y días de embarazo', 'Para calcular las semanas de embarazo, restá la fecha de tu última menstruación (FUM) a la fecha de hoy y dividí los días totales por 7. El resto son los días extras a la semana completa. Con FUM del 1 de marzo de 2026 y hoy 26 de mayo, tenés 86 días = 12 semanas y 2 días, segundo trimestre, 30% completado. La fecha…', 'salud', 'https://hacecuentas.com/calculadora-semanas-embarazo', 54);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-metabolismo-basal-bmr-tdee', 'Calculadora de metabolismo basal (BMR) y TDEE', 'Tu BMR (Basal Metabolic Rate) o metabolismo basal es la cantidad de calorías que tu cuerpo necesita solo para mantenerse vivo en reposo absoluto: respirar, hacer latir el corazón, regular la temperatura, mantener órganos y células funcionando. Representa entre el 60 % y el 70 % de tu gasto total diario.', 'salud', 'https://hacecuentas.com/calculadora-metabolismo-basal-bmr-tdee', 55);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-ladrillos-por-m2-construccion', '¿Cuántos ladrillos necesito por m²?', 'Para saber cuántos ladrillos necesitás por m² multiplicá los m² de pared por las unidades estándar según tipo y sumá 10% de desperdicio. Ladrillo hueco 18×18×33 cm: 16 unidades/m². Ladrillo común panderete: 63 u/m². Ladrillo común a soga: 52 u/m². Visto: 72 u/m². Bloque de hormigón 19×19×39: 12,5 u/m². Para una pared…', 'construccion', 'https://hacecuentas.com/calculadora-ladrillos-por-m2-construccion', 56);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-sueldo-por-hora', 'Calculadora de sueldo por hora en Argentina', 'Para sacar tu sueldo por hora, dividí el sueldo mensual en blanco por las horas mensuales según jornada. Con 48 h/semana (LCT) trabajás 208 h/mes; con 40 h/semana, 173,3 h/mes. Un sueldo de $1.200.000 con jornada de 48 h da $5.769 por hora, $46.150 por día y $96 por minuto. Usá 52 semanas anuales, no 48, para no…', 'finanzas', 'https://hacecuentas.com/calculadora-sueldo-por-hora', 57);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-edad-exacta-anos-meses-dias-segundos', 'Días hasta o desde una fecha', '¿Cuántos días faltan para ese evento importante? ¿Cuántos días pasaron desde que firmaste un contrato o empezaste un proyecto? Esta calculadora toma cualquier fecha — pasada o futura — y te dice exactamente cuántos días de diferencia hay respecto a hoy.', 'vida', 'https://hacecuentas.com/calculadora-edad-exacta-anos-meses-dias-segundos', 58);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-retencion-ganancias-rg-830', 'Retenciones de Ganancias a proveedores (RG 830 AFIP/ARCA)', 'La retención de Ganancias RG 830 se aplica al pagar a proveedores inscriptos por honorarios, alquileres, locaciones y comisiones. Se calcula sobre el excedente del mínimo no sujeto mensual del concepto. Honorarios profesionales usan escala progresiva de 5 % a 31 %. Si la retención es menor a $240 no se retiene…', 'finanzas', 'https://hacecuentas.com/calculadora-retencion-ganancias-rg-830', 59);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-bebidas-evento-litros-por-persona', 'Calculadora de bebidas para evento o fiesta', 'Para un evento de 4 a 5 horas, calculá 1 litro de bebida alcohólica más 1 litro de no alcohólica por persona. En 30 personas: 36 L de cerveza, 18 botellas de vino (750 ml), 6 L de fernet y 45 L de gaseosa o agua. En verano sumá 20% más; en invierno descontá 15%. Comprá siempre 10-15% extra.', 'cocina', 'https://hacecuentas.com/calculadora-bebidas-evento-litros-por-persona', 60);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-aleatorio-numero-dado', 'Generador de Número Aleatorio / Tirar Dado', 'Esta herramienta te permite tirar dados virtuales o generar números aleatorios dentro de un rango personalizado, de forma instantánea y sin sesgos. Podés simular un dado clásico de 6 caras, un dado de 20 caras (D20 de rol), o definir cualquier mínimo y máximo que necesités.', 'vida', 'https://hacecuentas.com/calculadora-aleatorio-numero-dado', 61);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-inflacion-acumulada-periodo', 'Calculadora de inflación acumulada por período', 'La inflación acumulada NO es la suma de tasas mensuales: se multiplican factores (1+tasa). Ejemplo: 5% mensual durante 12 meses = (1.05)^12 − 1 = 79.6% acumulada, no 60%. Los precios se multiplicaron por 1.80x.', 'finanzas', 'https://hacecuentas.com/calculadora-inflacion-acumulada-periodo', 62);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-agua-diaria-necesaria', 'Calculadora de Litros de Agua que Necesitás por Día', '¿Cuántos litros de agua necesitás tomar por día? No son los ''2 litros para todos'' — depende de tu peso, nivel de actividad y clima. Esta calculadora usa la fórmula de 35 ml por kg recomendada por la OMS, con ajustes personalizados.', 'vida', 'https://hacecuentas.com/calculadora-agua-diaria-necesaria', 63);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-aguinaldo-empleada-casa-particular-medio-tiempo-categoria', 'Calculadora de aguinaldo (SAC) de empleada de casa particular', 'El primer aguinaldo (SAC) de 2026 de la empleada de casa particular se paga hasta el 30 de junio de 2026. Está regulado por el Art. 39 de la Ley 26.844 (Régimen Especial para el Personal de Casas Particulares) y su fórmula es idéntica al régimen general (Ley 23.041): la mitad del mejor sueldo del semestre, prorrateado…', 'finanzas', 'https://hacecuentas.com/calculadora-aguinaldo-empleada-casa-particular-medio-tiempo-categoria', 64);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-talla-sosten-corpino', 'Calculadora de talla de corpiño/sostén', 'El 80% de las mujeres usa la talla incorrecta de corpiño según estudios de la industria. La talla correcta mejora la comodidad, la postura y el aspecto. Esta calculadora necesita solo 2 medidas: contorno bajo el busto y contorno del pecho en la parte más ancha.', 'salud', 'https://hacecuentas.com/calculadora-talla-sosten-corpino', 65);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-proteina-gramos-por-peso-actividad', 'Calculadora de proteína diaria por peso y nivel de actividad', 'La proteína es el macronutriente clave para la construcción muscular, la recuperación y la saciedad en dietas de definición. La cantidad que necesitás depende de tu peso corporal, tu nivel de actividad y tu objetivo. Esta calculadora usa los rangos recomendados por la ISSN (International Society of Sports Nutrition) y…', 'deportes', 'https://hacecuentas.com/calculadora-proteina-gramos-por-peso-actividad', 66);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-sueldo-empleada-domestica-horas-retiro', 'Sueldo empleada doméstica 2026 (por hora + retiro)', 'El sueldo del personal de casas particulares (Ley 26.844) se calcula por hora según la escala de la CNTCP, que varía por categoría y por modalidad —sin retiro paga más que con retiro—. Sueldo mensual ≈ valor hora × horas semanales × 4,33, más los aportes del empleador.', 'finanzas', 'https://hacecuentas.com/calculadora-sueldo-empleada-domestica-horas-retiro', 67);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-edad-perro-humano', 'Edad del Perro en Años Humanos', 'Olvidate de la regla del "× 7". La ciencia demostró que los perros envejecen de forma no lineal: maduran muy rápido los primeros dos años y después más lento. Esta calculadora usa la fórmula logarítmica publicada en 2019 por la UC San Diego (Wang et al., Cell Reports), basada en metilación del ADN.', 'mascotas', 'https://hacecuentas.com/calculadora-edad-perro-humano', 68);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-peso-ideal-bebe-mes-percentil', 'Calculadora de peso ideal del bebé por mes y percentil', 'Cada vez que llevás a tu bebé al control pediátrico, el médico anota el peso en una libreta o sistema digital y lo compara con una curva de crecimiento. Pero ¿qué significan exactamente esos números? ¿Es grave estar en el percentil 15? ¿Cuánto debería pesar tu bebé a los 4 meses?', 'salud', 'https://hacecuentas.com/calculadora-peso-ideal-bebe-mes-percentil', 69);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-cuota-alimentos-porcentaje-sueldo-hijo', 'Cuota alimentaria hijo', 'La cuota alimentaria es la suma de dinero que un progenitor debe pasar mensualmente al otro para cubrir las necesidades del hijo o hija menor: alimentación, salud, educación, vestimenta, esparcimiento y vivienda. En Argentina la regula el Código Civil y Comercial (arts.', 'finanzas', 'https://hacecuentas.com/calculadora-cuota-alimentos-porcentaje-sueldo-hijo', 70);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-ingresos-brutos-provincial', 'Ingresos Brutos (IIBB) por provincia', 'Para calcular Ingresos Brutos provincial multiplicá tu facturación mensual neta de IVA por la alícuota de tu jurisdicción y actividad. CABA general servicios: 5%. PBA comercio: 3,5%. Córdoba industria: 1%. Mendoza servicios: 4%. Ejemplo: consultor en CABA facturando $5.000.000/mes paga 5.000.000 × 5% = $250.000 de…', 'finanzas', 'https://hacecuentas.com/calculadora-ingresos-brutos-provincial', 71);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-liquidacion-final-empleada-casa-particular-despido-art-49', 'Calculadora de liquidación final por despido de empleada de casa particular', 'El régimen de las empleadas y empleados de casas particulares (lo que históricamente se llamaba servicio doméstico) se rige por la Ley 26.844, sancionada el 13 de marzo de 2013 y reglamentada por el Decreto 467/2014.', 'finanzas', 'https://hacecuentas.com/calculadora-liquidacion-final-empleada-casa-particular-despido-art-49', 72);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-millas-latam-destino', 'Millas LATAM LATAM Pass por destino', 'Para canjear pasajes con millas LATAM Pass necesitás entre 14.000 millas en economy ida y vuelta a destinos regionales como Buenos Aires o Santiago, 50.000 a Miami, 90.000-110.000 a Europa y 120.000 a Sydney. En business duplican o triplican los valores. Una milla LATAM vale aproximadamente 1,2 centavos de dólar y se…', 'viajes', 'https://hacecuentas.com/calculadora-millas-latam-destino', 73);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-paritaria-uocra-construccion-2026-categoria', 'Sueldo UOCRA construcción 2026 por categoría', 'Calculá el sueldo neto y bruto de un trabajador de la construcción según el convenio UOCRA 2026. Ingresá la categoría, la zona geográfica, los días trabajados y la antigüedad para obtener el salario básico, el fondo de cese, el presentismo y los descuentos de ley.', 'finanzas', 'https://hacecuentas.com/calculadora-paritaria-uocra-construccion-2026-categoria', 74);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('salario-minimo-vital-movil-argentina', 'Salario Mínimo Vital y Móvil Argentina (SMVM)', 'El Salario Mínimo Vital y Móvil (SMVM) es el piso legal de remuneración en Argentina: la cantidad mínima en dinero que debe percibir un trabajador en relación de dependencia mayor de 18 años por jornada legal completa de trabajo (48 horas semanales), sin cargas de familia. Está establecido por la Ley 20.744 (LCT) Art.', 'finanzas', 'https://hacecuentas.com/salario-minimo-vital-movil-argentina', 75);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-clearance-creatinina-cockcroft-gault', 'Calculadora de clearance de creatinina (Cockcroft-Gault)', 'La fórmula de Cockcroft-Gault (1976) calcula el clearance de creatinina: ClCr = [(140 − edad) × peso en kg] / (72 × creatinina sérica en mg/dL). En mujeres se multiplica por 0,85. Ejemplo: hombre 60 años, 80 kg, creatinina 1,2 mg/dL → ClCr = (80×80)/(72×1,2) = 74 ml/min, estadio 2. Valores normales >90 ml/min. Es la…', 'salud', 'https://hacecuentas.com/calculadora-clearance-creatinina-cockcroft-gault', 76);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-proteina-diaria-objetivo', 'Calculadora de proteína diaria recomendada', 'La recomendación de proteína varía muchísimo según tu objetivo. La RDA (Recommended Dietary Allowance) fijada por la OMS en 0,8 g/kg es un mínimo para evitar deficiencia en adultos sedentarios — no es un óptimo.', 'salud', 'https://hacecuentas.com/calculadora-proteina-diaria-objetivo', 77);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-edad-jubilacion-anos-aporte', 'Calculadora de jubilación — cuántos años te faltan', 'En Argentina, para jubilarte por ANSES necesitás cumplir dos requisitos simultáneos: tener la edad mínima (60 mujeres / 65 hombres) y 30 años de aportes al SIPA (Sistema Integrado Previsional Argentino). Esta calculadora te dice cuánto te falta para cada uno y en qué año estimado podrás jubilarte.', 'vida', 'https://hacecuentas.com/calculadora-edad-jubilacion-anos-aporte', 78);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-generacion-perteneces', 'Calculadora: ¿A Qué Generación Pertenecés?', 'Para saber a qué generación pertenecés según el año de nacimiento usá los rangos del Pew Research Center: Generación Alpha desde 2013, Gen Z de 1997 a 2012, Millennials de 1981 a 1996, Gen X de 1965 a 1980, Baby Boomers de 1946 a 1964, Generación Silenciosa de 1928 a 1945. Si naciste en 1990 sos Millennial, si naciste…', 'vida', 'https://hacecuentas.com/calculadora-generacion-perteneces', 79);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-calendario-ovulacion-ciclo-menstrual', 'Calculadora de calendario de ovulación y ciclo menstrual', 'Conocer tus días fértiles es clave tanto si buscás un embarazo como si querés evitarlo. La ovulación ocurre aproximadamente 14 días antes de tu próxima menstruación, y la ventana fértil abarca los 5 días previos a la ovulación + el día de la ovulación (6 días en total).', 'salud', 'https://hacecuentas.com/calculadora-calendario-ovulacion-ciclo-menstrual', 80);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-sueldo-gastronomico-uthgra-mozo-cocinero', 'Sueldo gastronómico UTHGRA 2026', 'El sueldo gastronómico UTHGRA 2026 se calcula sumando el básico por categoría del CCT 389/04 (mozo, cocinero, bachero, ayudante o encargado), antigüedad de 1% por año trabajado con tope de 20 años, adicional nocturno del 40% entre 21 y 6 horas, recargo del 100% en feriados y presentismo. Se descuentan aportes del 17%…', 'finanzas', 'https://hacecuentas.com/calculadora-sueldo-gastronomico-uthgra-mozo-cocinero', 81);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-consumo-nafta-litros-100km', 'Calculadora Consumo de Nafta L/100km', 'Para calcular el consumo de nafta en L/100km dividí los litros cargados por los kilómetros recorridos y multiplicá por 100. La fórmula es: consumo = (litros / km) × 100. Para obtener km/L dividí km recorridos por litros cargados. Un auto naftero promedio consume entre 8 y 12 L/100km en ciudad y entre 6 y 8 L/100km en…', 'automotor', 'https://hacecuentas.com/calculadora-consumo-nafta-litros-100km', 82);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-presion-atmosferica-altitud-barometrica', 'Calculadora de Presión Atmosférica según Altitud (Fórmula Barométrica)', 'Para calcular la presión atmosférica a cualquier altitud usá la fórmula barométrica ICAO: P(h) = 1013,25 × (1 − 0,0065·h / 288,15)^5,255, donde h es la altitud en metros. Al nivel del mar son 1013,25 hPa (760 mmHg). A 1.000 m: 899 hPa (~89%). A 3.000 m: 701 hPa (~69%). A 5.000 m: 540 hPa. En la cima del Everest (8.848…', 'ciencia', 'https://hacecuentas.com/calculadora-presion-atmosferica-altitud-barometrica', 83);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-jubilacion-anses-monto-minimo-maxima-2026', 'Jubilación ANSES 2026: mínima y máxima', 'La jubilación mínima ANSES 2026 ronda los $403.000 brutos mensuales más un bono de $70.000, totalizando unos $473.000. La jubilación máxima supera los $2.700.000. Las pensiones no contributivas (PNC) equivalen aproximadamente al 70% de la mínima. Los haberes se actualizan todos los meses por el IPC del INDEC con dos…', 'finanzas', 'https://hacecuentas.com/calculadora-jubilacion-anses-monto-minimo-maxima-2026', 84);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-edad-gato-humano-formula-anos', 'Edad gato a humano', '¿Tu gato tiene 5 años y querés saber «cuántos años tendría si fuera humano»? La respuesta no es tan simple como multiplicar por 7 — esa regla existe para perros medianos y encima está desactualizada. Los gatos envejecen de forma completamente distinta: los primeros dos años son turbo, y después el ritmo se estabiliza.', 'mascotas', 'https://hacecuentas.com/calculadora-edad-gato-humano-formula-anos', 85);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-ganancia-neta-uber-conductor-argentina', 'Calculadora de Ganancia Neta como Conductor de Uber en Argentina', 'Un conductor de Uber full-time en CABA bajo monotributo gana entre $800.000 y $1.400.000 netos por mes, tras descontar la comisión del 25% de Uber (que se aplica sobre la tarifa, no las propinas), Ingresos Brutos del 3% y el combustible. Como responsable inscripto perdés un 21% adicional por IVA. La ganancia es muy…', 'negocios', 'https://hacecuentas.com/calculadora-ganancia-neta-uber-conductor-argentina', 86);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-numeros-romanos-conversor', 'Conversor de Números Romanos', 'Para convertir un número decimal a romano se descompone en bloques (M=1000, CM=900, D=500, CD=400, C=100, XC=90, L=50, XL=40, X=10, IX=9, V=5, IV=4, I=1) y se concatenan las letras de mayor a menor. Por ejemplo, 2026 = MMXXVI y 1999 = MCMXCIX.', 'vida', 'https://hacecuentas.com/calculadora-numeros-romanos-conversor', 87);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('conversor-celsius-fahrenheit-temperatura', 'Conversor de Celsius a Fahrenheit', 'Convertir entre Celsius (°C), Fahrenheit (°F) y Kelvin (K) es una necesidad cotidiana: cuando mirás el pronóstico del clima de otro país, cocinás con recetas en °F, configurás un termostato importado, o estudiás termodinámica.', 'vida', 'https://hacecuentas.com/conversor-celsius-fahrenheit-temperatura', 88);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-peso-ideal-ninos', 'Calculadora de peso ideal para niños por edad y sexo', 'El peso ideal en niños es un rango saludable según edad y sexo definido por la OMS, no un número único. Un varón de 5 años tiene rango saludable entre 16 y 21 kg (percentil 15 a 85). Lo clave es que el niño siga su propia curva de crecimiento.', 'salud', 'https://hacecuentas.com/calculadora-peso-ideal-ninos', 89);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-credito-uva-cuota-actual', 'Calculadora de Cuota de Crédito UVA', 'La cuota de un crédito UVA se calcula con la fórmula francesa sobre el monto en UVAs y se multiplica por el valor UVA del día que publica el BCRA. Para 80.000 UVAs a tasa real 5,5 por ciento y 20 años, la cuota es 550 UVAs; con UVA de 1.200 pesos equivale a 660.000 pesos mensuales. El UVA ajusta por CER según la…', 'finanzas', 'https://hacecuentas.com/calculadora-credito-uva-cuota-actual', 90);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-cuota-prestamo', 'Calculadora de cuota de préstamo', 'La cuota de un préstamo por sistema francés se calcula con la fórmula: cuota = capital × (i × (1+i)^n) / ((1+i)^n − 1), donde i es la tasa mensual y n los meses. Para $5.000.000 a TNA 85 % y 36 meses, la cuota es aprox. $387.000 y se pagan $8.9 millones de intereses totales. Comparar siempre por CAE (no por TNA)…', 'finanzas', 'https://hacecuentas.com/calculadora-cuota-prestamo', 91);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-presentismo-puntualidad', 'Calculadora de Presentismo y Puntualidad', 'El adicional por presentismo en Argentina se calcula como porcentaje del sueldo básico según el convenio colectivo: Empleados de Comercio CCT 130/75 paga 8,33% del básico, Gastronómicos CCT 389/04 paga 10%, Metalúrgicos UOM 8%. Se pierde escalonadamente: 1 ausencia injustificada = se descuenta 33%, 2 ausencias = 67%…', 'finanzas', 'https://hacecuentas.com/calculadora-presentismo-puntualidad', 92);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-tamano-aire-acondicionado-btu-habitacion', 'Calculadora de BTU para aire acondicionado', 'Elegir un aire acondicionado del tamaño correcto es clave: uno chico no enfría y uno grande gasta de más. La capacidad se mide en BTU/h (o frigorías). Esta calculadora estima los BTU necesarios para tu ambiente según los metros cuadrados, la altura del techo, la orientación solar y el nivel de aislación.', 'vida', 'https://hacecuentas.com/calculadora-tamano-aire-acondicionado-btu-habitacion', 93);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-costo-supermercado-canasta-basica', 'Calculadora de costo de canasta básica mensual', 'El gasto mensual en supermercado = adultos equivalentes (adultos × 1,0 + menores × 0,63) × CBA por AE × factor de consumo (básico 1,0 / moderado 1,3 / premium 1,8). Familia tipo de 4 con consumo moderado: ~$460.000/mes (2026).', 'vida', 'https://hacecuentas.com/calculadora-costo-supermercado-canasta-basica', 94);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-jubilacion-minima-anses', 'Jubilación mínima ANSES (haber + bono)', 'La jubilación mínima ANSES en junio 2026 es de $473.318 mensuales (haber mínimo $403.318 + bono complementario $70.000). Se ajusta mensualmente por IPC INDEC (movilidad del DNU 274/2024 que modifica la Ley 24.241). Incluye cobertura PAMI gratis y dos medios aguinaldos en junio y diciembre, calculados solo sobre el…', 'finanzas', 'https://hacecuentas.com/calculadora-jubilacion-minima-anses', 95);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-percentil-bebe-oms', 'Calculadora de percentil del bebé (peso y talla OMS)', 'Las curvas de crecimiento de la OMS son el estándar mundial para evaluar si tu bebé está creciendo bien. Miden peso, talla/longitud y perímetro cefálico comparándolos con miles de bebés sanos de distintas poblaciones. Esta calculadora te dice en qué percentil está tu bebé según su edad y sexo.', 'salud', 'https://hacecuentas.com/calculadora-percentil-bebe-oms', 96);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-sucesion-costo', 'Calculadora de Costo de una Sucesión', 'Una sucesión en Argentina cuesta entre 6% y 15% del valor del acervo hereditario. Incluye honorarios del abogado (3 a 12%), tasa de justicia (1,5 a 3%), aportes a caja de abogados (1 a 2%) y gastos administrativos. Un acervo de 50 millones de pesos paga entre 3 y 7,5 millones en total, con plazo de 6 meses a 2 años.', 'vida', 'https://hacecuentas.com/calculadora-sucesion-costo', 97);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-consumo-electrico-kwh-factura-luz', 'Calculadora de consumo eléctrico: kWh y costo de la factura', 'Para calcular el consumo eléctrico en kWh, multiplicá la potencia del electrodoméstico en watts por las horas de uso diario y dividilo por 1.000. Multiplicando ese resultado por el precio del kWh de tu factura (entre 40 y 120 pesos según segmentación N1, N2 o N3) obtenés el costo mensual. Los aparatos que más consumen…', 'vida', 'https://hacecuentas.com/calculadora-consumo-electrico-kwh-factura-luz', 98);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-sueldo-bruto-desde-neto', 'Calculadora de Sueldo Bruto desde Neto Deseado', 'Si sabés cuánto querés cobrar en mano (neto) y necesitás saber cuánto tiene que ser tu sueldo bruto, esta calculadora hace el cálculo inverso 2026.', 'finanzas', 'https://hacecuentas.com/calculadora-sueldo-bruto-desde-neto', 99);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-horas-extras-50-100', 'Calculadora de Horas Extras al 50% y 100%', 'El valor de la hora extra al 50% se calcula dividiendo el sueldo bruto mensual por 200 horas y multiplicando por 1,5; la hora al 100% (sábados después de 13hs, domingos y feriados) se multiplica por 2. Con un sueldo bruto de 1.500.000 pesos, la hora normal vale 7.500, la hora al 50% vale 11.250 y la hora al 100% vale…', 'finanzas', 'https://hacecuentas.com/calculadora-horas-extras-50-100', 100);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-pintura-por-m2-litros-latas', '¿Cuántos litros de pintura necesito?', 'Para calcular los litros de pintura, multiplicá los m² por las manos (2 mínimo) y dividí por el rendimiento real. Látex interior rinde unos 12 m² por litro por mano; exterior, 10 m². Para 100 m² con 2 manos de látex interior: 100 × 2 ÷ 12 = 17 litros (una lata de 20 L). Sumá 10% por desperdicio. Si cambiás de color…', 'construccion', 'https://hacecuentas.com/calculadora-pintura-por-m2-litros-latas', 101);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-resistencia-codigo-colores-4-5-bandas', 'Calculadora de resistencia por código de colores', 'Cuando tenés una resistencia en la mano y necesitás saber exactamente cuántos ohms vale, el código de colores pintado en su cuerpo es la única información disponible, pero descifrarla de memoria es frustrante incluso para técnicos con años de experiencia. ¿Es marrón o negro? ¿Rojo o naranja? ¿Desde qué lado la leo?', 'electronica', 'https://hacecuentas.com/calculadora-resistencia-codigo-colores-4-5-bandas', 102);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-pintura-paredes-habitacion-litros', 'Calculadora de litros de pintura para paredes', 'Pintar una habitación parece simple, pero calcular mal la cantidad de litros de pintura es un error caro: comprar de más es desperdicio y de menos significa volver a la pinturería a mitad de trabajo.', 'vida', 'https://hacecuentas.com/calculadora-pintura-paredes-habitacion-litros', 103);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-conversion-tna-tem-tea', 'Calculadora de Conversión TNA ↔ TEM ↔ TEA', 'En Argentina convivís con tres tasas que parecen lo mismo pero son muy diferentes: la TNA (Tasa Nominal Anual), la TEM (Tasa Efectiva Mensual) y la TEA (Tasa Efectiva Anual). Bancos, financieras y exchanges usan una u otra según les convenga.', 'finanzas', 'https://hacecuentas.com/calculadora-conversion-tna-tem-tea', 104);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-costo-financiero-total-cft', 'Calculadora de Costo Financiero Total (CFT)', 'El Costo Financiero Total se calcula sumando a la tasa nominal anual el IVA sobre intereses, los seguros obligatorios y los gastos administrativos. La fórmula técnica usa la TIR del flujo de fondos real del préstamo. Un crédito a 80 por ciento de TNA con seguros de 5.000 pesos y 21 por ciento de IVA termina costando…', 'finanzas', 'https://hacecuentas.com/calculadora-costo-financiero-total-cft', 105);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-gastos-escritura-compraventa', 'Calculadora de Gastos de Escritura', 'Los gastos de escritura en Argentina rondan entre el 3% y 7% del valor de la operación para el comprador (honorarios escribano 1-2% + IVA, sellos 2-3,6% según jurisdicción, certificados ~$200.000) y 1,5% de ITI para el vendedor. En CABA, comprar un departamento de $50 millones cuesta unos $3,2 millones extras en…', 'finanzas', 'https://hacecuentas.com/calculadora-gastos-escritura-compraventa', 106);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-comprar-anos-aportes-moratoria-previsional-cuotas', 'Calculadora de moratoria previsional: comprar años de aportes', 'La Ley 27.705 (Plan de Pago de Deuda Previsional) permitió "comprar" años de aportes faltantes. Atención 2026: la adhesión para quienes YA cumplieron la edad jubilatoria venció el 23/03/2025 y no fue prorrogada; sigue disponible solo el régimen de regularización para trabajadores en actividad a menos de 10 años de la…', 'finanzas', 'https://hacecuentas.com/calculadora-comprar-anos-aportes-moratoria-previsional-cuotas', 107);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-mundial-2026-predictor-campeon-ranking', 'Mundial 2026 — Predictor de campeón según ranking FIFA y bombo', 'Apenas 8 selecciones distintas ganaron un Mundial en 22 ediciones jugadas: Brasil (5), Italia y Alemania (4), Argentina y Uruguay (3 y 2 respectivamente), Francia (2), España (1) e Inglaterra (1). La conclusión histórica es contundente: el club de campeones es chiquito y muy poblado de europeos y sudamericanos.', 'deportes', 'https://hacecuentas.com/calculadora-mundial-2026-predictor-campeon-ranking', 108);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-estimador-costo-viaje-taxi-remis', 'Estimador de costo de viaje en taxi o remis', 'El precio del remis por km en 2026 ronda los $380 en CABA (entre $320 y $380 en el interior), más una bajada de bandera de unos $950 y $60 por minuto de espera. El costo total = bajada de bandera + (km × precio por km) + (minutos × precio por minuto). Un viaje de 5 km en 15 minutos sale cerca de $3.750; los recargos…', 'vida', 'https://hacecuentas.com/calculadora-estimador-costo-viaje-taxi-remis', 109);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-porcion-arroz-gramos-personas', 'Calculadora de gramos de arroz por persona', 'Esta calculadora te dice exactamente cuántos gramos de arroz crudo necesitás según la cantidad de comensales, el tipo de plato y si hay niños en la mesa.', 'cocina', 'https://hacecuentas.com/calculadora-porcion-arroz-gramos-personas', 110);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-impuesto-sellos-inmueble-contrato', 'Calculadora de impuesto de sellos (inmueble / contrato)', 'El impuesto de sellos sobre un contrato de alquiler o compraventa se calcula multiplicando el monto total del contrato por la alícuota provincial. Alícuotas 2026: CABA 0,5% alquileres y 2,5% compraventas; Buenos Aires 1% y 2%; Córdoba 1,5% y 2%. Habitualmente se paga 50% cada parte. La base imponible es la suma total…', 'finanzas', 'https://hacecuentas.com/calculadora-impuesto-sellos-inmueble-contrato', 111);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-split-gastos-grupo-amigos', 'Calculadora para dividir gastos entre amigos', 'Dividir gastos entre amigos parece simple, pero cuando cada uno pagó cosas distintas se complica rápido. Esta calculadora toma el gasto total, la cantidad de personas y cuánto puso cada uno, y te dice quién debe a quién y cuánto. Ideal para viajes, cenas, alquileres de vacaciones o cualquier gasto compartido.', 'finanzas', 'https://hacecuentas.com/calculadora-split-gastos-grupo-amigos', 112);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-ciclo-menstrual', 'Calculadora del ciclo menstrual', 'Para predecir la próxima menstruación, sumá la duración de tu ciclo (21-35 días) al primer día de la última menstruación (FUM). La ovulación cae aproximadamente en el día 14 (ciclo de 28) o duración_ciclo − 14.', 'salud', 'https://hacecuentas.com/calculadora-ciclo-menstrual', 113);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-corte-optimo-tablero', 'Calculadora de corte óptimo de tablero de MDF/melamina', 'En un tablero estándar de MDF de 183×274 cm caben 36 piezas de 40×30 cm con corte optimizado (6 columnas × 6 filas), generando 13,8% de desperdicio. Para piezas de 80×60 cm caben 9 por tabla. La fórmula básica: piezas_x = floor(largo_tabla / largo_pieza), considerando 3 mm de sierra por corte. Rotar piezas 90° puede…', 'construccion', 'https://hacecuentas.com/calculadora-corte-optimo-tablero', 114);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-palabras-paginas-conversor', 'Conversor de palabras a páginas', '1000 palabras equivalen a 4 páginas con interlineado doble (250 palabras por página, Times 12pt) o 2 páginas con interlineado simple (500 palabras por página). La fórmula es palabras dividido palabras-por-página según interlineado: 250 por página a doble, 375 a 1.5 y 500 a simple. Leer 1000 palabras lleva 5 minutos a…', 'educacion', 'https://hacecuentas.com/calculadora-palabras-paginas-conversor', 115);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-sueldo-docente-argentina-cargo-antiguedad', 'Sueldo docente Argentina 2026 (cargo + antigüedad)', 'El sueldo docente en Argentina 2026 combina un básico por cargo (maestro, profesor, preceptor, vice o director) más antigüedad (10% por año) y horas frente al curso, con descuentos de jubilación, obra social y PAMI. Esta calculadora parte del piso salarial mínimo docente garantizado por la paritaria nacional 2026…', 'finanzas', 'https://hacecuentas.com/calculadora-sueldo-docente-argentina-cargo-antiguedad', 116);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-diferencia-horaria-ciudades-paises', 'Calculadora de Diferencia Horaria entre Ciudades', 'Saber la diferencia horaria entre ciudades es esencial para coordinar llamadas de trabajo, planificar vuelos y evitar despertar a alguien a las 3 AM. Esta calculadora te muestra la diferencia en horas entre 14 ciudades principales del mundo, incluyendo las más consultadas desde Argentina: Madrid, Nueva York, Miami…', 'viajes', 'https://hacecuentas.com/calculadora-diferencia-horaria-ciudades-paises', 117);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-impuesto-cheque-debitos-creditos', 'Impuesto a los Débitos y Créditos Bancarios (Ley 25.413)', 'El impuesto al cheque (Ley 25.413) grava cada movimiento bancario con 0,6% por débito y 0,6% por crédito, totalizando 1,2% en una operación redonda. Aplica a transferencias, pagos con débito, billeteras virtuales (Mercado Pago, Ualá) y cheques. Cuentas sueldo y cajas de jubilación están exentas. Las PyME acreditadas…', 'finanzas', 'https://hacecuentas.com/calculadora-impuesto-cheque-debitos-creditos', 118);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-litros-nafta-viaje-ruta-argentina', 'Calculadora de Litros de Nafta para un Viaje por Ruta', 'Para calcular los litros de nafta de un viaje por ruta, multiplicá la distancia (km) por el consumo del auto (L/100 km) y dividí por 100. Por ejemplo: 400 km × 8 L/100 km / 100 = 32 litros. A $1.100 el litro de nafta súper, el costo de combustible es $35.200. Sumá peajes y restaurá un margen del 10% para condiciones…', 'viajes', 'https://hacecuentas.com/calculadora-litros-nafta-viaje-ruta-argentina', 119);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-neumaticos-medida-equivalente', 'Calculadora Neumáticos — Medida Equivalente', 'Las medidas de neumáticos como 195/65 R15 parecen un código secreto, pero son simples: ancho/perfil Rdiámetro. Esta calculadora te decodifica cualquier medida, calcula el diámetro total del neumático y te ayuda a encontrar medidas equivalentes si querés cambiar el tamaño de las ruedas manteniendo el mismo diámetro…', 'automotor', 'https://hacecuentas.com/calculadora-neumaticos-medida-equivalente', 120);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-porcentaje-grasa-corporal', 'Calculadora de porcentaje de grasa corporal', 'US Navy = cinta métrica + cuello + cintura (+ cadera en mujeres). Un hombre entre 14–17 % o una mujer entre 21–24 % entra en rango fitness. Bajo 6 % (hombres) o 14 % (mujeres) es grasa esencial — no sostenible a largo plazo.', 'salud', 'https://hacecuentas.com/calculadora-porcentaje-grasa-corporal', 121);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-presion-arterial-rango', '¿Tu presión arterial es normal?', 'La presión arterial es uno de los indicadores más importantes de salud cardiovascular. Se mide con dos números: sistólica (cuando el corazón bombea) y diastólica (cuando descansa). Esta calculadora clasifica tu presión según la guía AHA/ACC 2017 y te dice si es normal, elevada o si necesitás consultar al médico.', 'salud', 'https://hacecuentas.com/calculadora-presion-arterial-rango', 122);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-tamano-tv-distancia-ideal-pulgadas', 'Calculadora de tamaño de TV ideal según distancia', 'Comprar una TV del tamaño correcto depende casi exclusivamente de a qué distancia te sentás. Un televisor demasiado chico te hace forzar la vista; uno demasiado grande genera fatiga visual y no podés abarcar la imagen entera.', 'vida', 'https://hacecuentas.com/calculadora-tamano-tv-distancia-ideal-pulgadas', 123);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-cantidad-ladrillos-metro-cuadrado-pared', 'Ladrillos por m² pared', 'Antes de comprar un solo ladrillo, necesitás saber cuántos van a entrar en tu pared — y esa cuenta no es tan obvia como parece. El tipo de ladrillo, el espesor de la pared y el aparejo elegido cambian radicalmente la cantidad.', 'construccion', 'https://hacecuentas.com/calculadora-cantidad-ladrillos-metro-cuadrado-pared', 124);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-colesterol-total-ldl-hdl-valores-deseables', 'Colesterol total/LDL/HDL', 'Cuando el médico te entrega el resultado del lipidograma, los números solos no dicen mucho si no sabés contra qué compararlos. Colesterol total de 210, LDL de 130, HDL de 45: ¿es preocupante? ¿está bien? ¿cambia algo según tu sexo? Esas preguntas son exactamente las que esta calculadora te ayuda a responder.', 'salud', 'https://hacecuentas.com/calculadora-colesterol-total-ldl-hdl-valores-deseables', 125);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-ganancias-empleados-4ta-categoria-2026', 'Ganancias 4ta Categoría 2026 — Impuesto para Empleados', 'El impuesto a las Ganancias de 4ta categoría grava los sueldos de empleados en relación de dependencia. Desde la Ley 27.743, se actualizó el piso y la escala. Esta calculadora te dice cuánto te retienen según tu sueldo bruto, cargas de familia y deducciones.', 'finanzas', 'https://hacecuentas.com/calculadora-ganancias-empleados-4ta-categoria-2026', 126);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-jubilacion-docente-caba', 'Calculadora de jubilación docente CABA', 'Los docentes de CABA jubilan por ANSES con régimen especial docente (Ley 24.016 y modificatorias): el haber es el 82% del promedio de las 120 mejores remuneraciones actualizadas de los últimos 10 años de servicio. La obra social post-jubilatoria pasa por ObSBA (Obra Social de la Ciudad) o por PAMI según el caso.', 'finanzas', 'https://hacecuentas.com/calculadora-jubilacion-docente-caba', 127);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-comparador-messi-vs-cristiano-goles-asistencias-titulos', 'Comparador Messi vs Cristiano Ronaldo: goles, asistencias, títulos y Mundiales', 'Desde 2008 hasta hoy, el debate entre <strongLionel Messi y Cristiano Ronaldo</strong partió al mundo futbolero en dos. Es el único debate deportivo que sobrevivió casi dos décadas sin resolverse, y la razón es simple: depende de qué métrica mirás. Si mirás goles totales, gana Cristiano.', 'deportes', 'https://hacecuentas.com/calculadora-comparador-messi-vs-cristiano-goles-asistencias-titulos', 128);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-formula-citacion-apa', 'Generador de Citas APA 7ma Edición', 'El formato APA 7ma edición es el estándar más usado para citas bibliográficas en ciencias sociales, psicología y educación. Esta calculadora genera la referencia completa en formato APA a partir de los datos básicos: autor, año, título y fuente.', 'educacion', 'https://hacecuentas.com/calculadora-formula-citacion-apa', 129);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-sueldo-camionero-fedcam-basico-adicionales', 'Sueldo camionero 2026 (Fedcam)', 'El sueldo del camionero argentino se arma con varias capas: básico de convenio según categoría (conductor primera, conductor cargas peligrosas, ayudante, etc.), más adicionales remunerativos (antigüedad 1% por año, título, zona desfavorable), más no remunerativos negociados por FEDCAM en cada paritaria, más ítems…', 'finanzas', 'https://hacecuentas.com/calculadora-sueldo-camionero-fedcam-basico-adicionales', 130);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-aportes-patronales-empleado-registrado-cargas-sociales-2026', 'Calculadora de aportes patronales y cargas sociales del empleador', 'Las contribuciones patronales en Argentina están reguladas por el Decreto 814/2001 (con modificaciones de la Ley 27.430 y posteriores) y reglamentadas mediante resoluciones generales de ARCA (ex-AFIP).', 'finanzas', 'https://hacecuentas.com/calculadora-aportes-patronales-empleado-registrado-cargas-sociales-2026', 131);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-asignacion-desempleo-seguro-prestacion-anses', 'Seguro desempleo ANSES', 'Quedarse sin trabajo es un golpe duro. Saber cuánto vas a cobrar del seguro de desempleo ANSES es lo primero que necesitás resolver para planificar los próximos meses.', 'finanzas', 'https://hacecuentas.com/calculadora-asignacion-desempleo-seguro-prestacion-anses', 132);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-edad-corregida-prematuro', 'Calculadora de edad corregida para bebés prematuros', 'La edad corregida de un prematuro se calcula restando las semanas de prematurez a la edad cronológica. La prematurez es 40 menos las semanas de gestación al nacer. Un bebé nacido a las 32 semanas tiene 8 semanas de descuento: si hoy tiene 5 meses cronológicos, su corregida es 3 meses. SAP y AAP recomiendan usarla…', 'salud', 'https://hacecuentas.com/calculadora-edad-corregida-prematuro', 133);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-ganancias-4ta-categoria-2026', 'Ganancias 4ta categoría 2026', 'Ganancias 4ta categoría 2026 grava sueldos de empleados en relación de dependencia con bruto anual superior a ~$28.000.000 (soltero sin cargas) o más con cargas familiares. La fórmula resta aportes (17%), MNI ($5.151.802), Deducción Especial 4ta ($18.031.308) y aplica escala progresiva del Art. 94 LIG con tramos del…', 'finanzas', 'https://hacecuentas.com/calculadora-ganancias-4ta-categoria-2026', 134);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-grasa-corporal-pliegues', 'Calculadora de % grasa corporal por pliegues cutáneos', 'La fórmula Jackson-Pollock de 3 pliegues cutáneos estima el porcentaje de grasa corporal con error ±3-4%. Hombres miden pecho + abdomen + muslo; mujeres tríceps + suprailiaco + muslo. La suma se convierte en densidad corporal y luego en % grasa con la ecuación de Siri: %grasa = (495/densidad) − 450. Rango saludable…', 'deportes', 'https://hacecuentas.com/calculadora-grasa-corporal-pliegues', 135);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-watts-fuente-alimentacion-pc', 'Calculadora de watts necesarios en fuente de PC', 'La calculadora de watts para fuente de PC suma el consumo de GPU, CPU, RAM y discos, y agrega el margen de seguridad recomendado. Así sabés exactamente qué capacidad y certificación 80 PLUS necesitás antes de comprar. Un RTX 4070 + i7 13700 + 32 GB estima 460 W y requiere fuente de 750 W Gold.', 'tecnologia', 'https://hacecuentas.com/calculadora-watts-fuente-alimentacion-pc', 136);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-consumo-combustible-km-litro', 'Consumo combustible km/L', 'El surtidor no miente, pero el odómetro tampoco. Si tu auto debería hacer 14 km/L según el manual y en la vida real te da 10, hay algo que no está funcionando bien: puede ser un sensor MAF sucio, inyectores sucios, bujías gastadas, neumáticos bajos o simplemente el tráfico porteño destrozando tu rendimiento.', 'automotor', 'https://hacecuentas.com/calculadora-consumo-combustible-km-litro', 137);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-peso-objetivo-competicion', 'Calculadora de peso ideal según deporte y altura', 'El peso ideal competitivo se calcula con Peso Devine (kg) = Base + 0,9 × (altura en cm − 152,4), ajustado por deporte: resistencia −5 a −10%, fuerza +5 a +15%, combate según categoría oficial. Por ejemplo, un varón de 1,78 m tiene un Devine de ~72,7 kg; como judoca competiría en la categoría de −73 kg de IJF.', 'deportes', 'https://hacecuentas.com/calculadora-peso-objetivo-competicion', 138);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-hemoglobina-glicosilada-a1c-glucosa', 'Calculadora de HbA1c y glucosa promedio estimada', 'La HbA1c refleja la glucemia promedio de los últimos 2-3 meses. Fórmula ADAG: glucosa promedio (mg/dL) = 28,7 × A1c (%) − 46,7. HbA1c 7 % equivale a 154 mg/dL. Criterios ADA: menos de 5,7 % normal, 5,7-6,4 % prediabetes, 6,5 % o más diabetes.', 'salud', 'https://hacecuentas.com/calculadora-hemoglobina-glicosilada-a1c-glucosa', 139);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-duracion-bateria-mah-consumo', 'Calculadora Duración de Batería — mAh y Consumo', 'Cuánto dura una batería en mAh depende de cuántos mA consume el dispositivo: horas = (mAh × 0,85) ÷ mA, donde 0,85 es la eficiencia real promedio. Una batería de 400 mAh que consume 100 mA dura unas 3,4 horas; un celular de 5.000 mAh con 500 mA de consumo normal dura ~8,5 horas, y jugando juegos pesados con 1.500 mA…', 'tecnologia', 'https://hacecuentas.com/calculadora-duracion-bateria-mah-consumo', 140);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-pension-viudez-porcentaje-conyuge', 'Pensión viudez: porcentaje cónyuge', 'En la pensión por fallecimiento (Ley 24.241, art. 98), el cónyuge cobra el 70% del haber del fallecido si no hay hijos con derecho y el 50% si los hay; cada hijo percibe el 20% aparte. Si la suma supera el 100% del haber, se prorratea.', 'finanzas', 'https://hacecuentas.com/calculadora-pension-viudez-porcentaje-conyuge', 141);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-rendimiento-masa-empanadas-cantidad', 'Calculadora de rendimiento de masa para empanadas', 'Para saber cuántas empanadas salen, dividí el peso total de la masa por el peso de una tapa: 30-35 g cada una en tamaño mediano. Con 1 kg de harina salen unas 30-35 tapas. Si comprás tapas en paquete, vienen 12 unidades por paquete. Para 50 empanadas medianas necesitás 1,5 kg de harina o 5 paquetes de tapas. Sumá 600…', 'cocina', 'https://hacecuentas.com/calculadora-rendimiento-masa-empanadas-cantidad', 142);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-semanas-gestacion-ecografia', 'Calculadora de semanas de gestación por ecografía', 'Para calcular las semanas de gestación según la ecografía usá la longitud cráneo-caudal (LCC) en el primer trimestre o el diámetro biparietal (DBP) en el segundo. La LCC entre 1 y 84 mm corresponde a las semanas 6 a 13 con ±5 días de precisión. Un LCC de 45 mm equivale aproximadamente a 11 semanas y 3 días. La…', 'salud', 'https://hacecuentas.com/calculadora-semanas-gestacion-ecografia', 143);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-indice-glucemico-por-alimento', 'Calculadora de Índice Glucémico (IG) por Alimento', 'El índice glucémico (IG) mide qué tan rápido un alimento con carbohidratos eleva la glucosa en sangre comparado con glucosa pura (IG=100). Fue desarrollado en 1981 por David Jenkins (Universidad de Toronto) y validado por la Universidad de Sidney, que mantiene la base de datos GI más completa del mundo.', 'salud', 'https://hacecuentas.com/calculadora-indice-glucemico-por-alimento', 144);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-framingham-riesgo-cardiovascular', 'Calculadora de riesgo cardiovascular Framingham', 'El Framingham Risk Score es la calculadora más usada del mundo para estimar el riesgo de evento cardiovascular (infarto o ACV) a 10 años. Surge del estudio Framingham Heart Study (Massachusetts, 1948-presente), el primer estudio epidemiológico cardiovascular masivo.', 'salud', 'https://hacecuentas.com/calculadora-framingham-riesgo-cardiovascular', 145);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-patente-ciclomotor-moto-argentina-costo', 'Patente moto/ciclomotor AR', 'La patente de motos y ciclomotores en Argentina es un tributo provincial/municipal que grava la radicación del vehículo en el domicilio del titular.', 'automotor', 'https://hacecuentas.com/calculadora-patente-ciclomotor-moto-argentina-costo', 146);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-edad-humana-por-raza-perro', 'Edad humana del perro según raza', 'Durante décadas, el cálculo fue simple: multiplicar por 7. Si tu perro tiene 3 años, tiene 21 humanos. Fácil, prolijo… y completamente incorrecto.', 'mascotas', 'https://hacecuentas.com/calculadora-edad-humana-por-raza-perro', 147);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-honorarios-abogado', 'Calculadora de Honorarios de Abogado', 'Los honorarios de abogado en Argentina van del 11% al 20% del monto del juicio (civil/comercial/laboral) y 3% al 12% del acervo en sucesiones, según Ley 27.423. Pacto de cuota litis máximo legal 40%. Si es Responsable Inscripto suma 21% de IVA.', 'vida', 'https://hacecuentas.com/calculadora-honorarios-abogado', 148);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-valuacion-fiscal-automotor-argentina', 'Calculadora de Valuación Fiscal Automotor en Argentina (impuesto por provincia 2026)', 'Esta calculadora estima el impuesto automotor (patente) anual en cualquier provincia argentina cruzando la valuación fiscal oficial de ARCA (ex-AFIP) con la alícuota provincial vigente 2026.', 'automotor', 'https://hacecuentas.com/calculadora-valuacion-fiscal-automotor-argentina', 149);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-aumento-alquiler-trimestral-cuatrimestral-semestral', 'Aumento alquiler según frecuencia', 'Con inflación mensual constante, un alquiler ajustado por capitalización compuesta llega al mismo monto a los 12 meses sea trimestral, cuatrimestral, semestral o anual: el factor es (1 + inflación mensual)¹². La frecuencia solo cambia cuándo se paga y cómo pega si la inflación se mueve.', 'finanzas', 'https://hacecuentas.com/calculadora-aumento-alquiler-trimestral-cuatrimestral-semestral', 150);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-stream-bitrate-calidad', 'Calculadora de Bitrate Ideal para Streaming', 'Para 720p60 usá entre 3.500 y 5.000 kbps, para 1080p60 en Twitch el máximo es 6.000 kbps y en YouTube hasta 12.000 kbps. Tu upload debe ser al menos 1,5 veces el bitrate elegido para evitar dropped frames. El encoder NVENC (GPU NVIDIA) no impacta el rendimiento del juego, mientras que x264 (CPU) da mejor calidad a…', 'entretenimiento', 'https://hacecuentas.com/calculadora-stream-bitrate-calidad', 151);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-deficit-calorico-perder-peso', 'Calculadora de deficit calorico para perder peso', 'Perder peso se reduce a un principio simple: gastar mas calorias de las que consumis. Ese gap es el deficit calorico. Para perder medio kilo de grasa necesitas un deficit acumulado de ~3.500 kcal. Pero ojo: un deficit demasiado agresivo (mas de 1.000 kcal/dia) puede causar perdida muscular, fatiga y efecto rebote.', 'salud', 'https://hacecuentas.com/calculadora-deficit-calorico-perder-peso', 152);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-ganancias-aguinaldo-sac-retencion', 'Ganancias sobre aguinaldo (SAC)', 'El Impuesto a las Ganancias sobre el aguinaldo tiene un esquema particular: la AFIP exige prorratear el SAC mes a mes como si fuera una doceava parte del salario devengado cada mes, desde enero, en vez de gravarlo íntegro en junio y diciembre.', 'finanzas', 'https://hacecuentas.com/calculadora-ganancias-aguinaldo-sac-retencion', 153);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-esperanza-vida-gato-raza-indoor', 'Cuántos años vive un gato según raza y estilo de vida', 'La esperanza de vida de un gato varía enormemente según su estilo de vida: un gato indoor (que vive solo adentro) vive en promedio 15-20 años, mientras que un gato outdoor (que sale a la calle) vive 3-7 años en promedio por accidentes, peleas, enfermedades y atropellos.', 'mascotas', 'https://hacecuentas.com/calculadora-esperanza-vida-gato-raza-indoor', 154);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-horario-llegada-zona-horaria', 'Hora local de llegada según zona horaria y duración de vuelo', '¿Salís a las 23:00 de Buenos Aires rumbo a Madrid con 11h 30m de vuelo? ¿A qué hora llegás hora local? No es sumar 11:30 a las 23:00 y listo: tenés que sumar también las 4 horas de diferencia horaria (o 5 según el horario de verano europeo).', 'viajes', 'https://hacecuentas.com/calculadora-horario-llegada-zona-horaria', 155);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-velocidad-internet-mbps-real', 'Calculadora Velocidad de Internet Mbps Real vs Contratada', 'Pagás por 300 Mbps pero sentís que internet va lento. ¿Tu proveedor te está dando lo que prometió? Con esta calculadora ingresás la velocidad contratada y la velocidad real (medida con speedtest) y obtenés el porcentaje de cumplimiento, si estás dentro de lo aceptable y cuánto dinero estás perdiendo proporcionalmente.', 'tecnologia', 'https://hacecuentas.com/calculadora-velocidad-internet-mbps-real', 156);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-monotributo-categoria-2026-recategorizacion-julio', 'Recategorización Monotributo Julio 2026', 'La recategorización de monotributo de julio 2026 cierra el 5 de agosto de 2026 (el portal de ARCA abre alrededor del 15 de julio) y toma tu facturación de los últimos 12 meses. El tope máximo es $108.357.084 anuales (categoría K, igual para servicios y venta de bienes desde la reforma 2026); superarlo implica pasar a…', 'impuestos', 'https://hacecuentas.com/calculadora-monotributo-categoria-2026-recategorizacion-julio', 157);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-pisos-ceramicos-porcellanato-cajas', '¿Cuántas cajas de cerámico o porcellanato necesito?', 'Cajas = redondeararriba((m²ambiente × (1 + desperdicio%)) / m²porcaja). Piezas estándar 60×60 vienen en cajas de 1,44 m² (4 piezas). Para un ambiente rectangular usá 10% desperdicio, para diagonal 15-20%.', 'construccion', 'https://hacecuentas.com/calculadora-pisos-ceramicos-porcellanato-cajas', 158);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-alcohol-sangre-bac', 'Calculadora de alcohol en sangre (BAC)', 'En Argentina rige desde enero de 2023 la Ley 27.714 de Alcohol Cero al Volante: cero tolerancia para conducir cualquier vehículo motorizado. No hay margen legal, ni medio vaso.', 'salud', 'https://hacecuentas.com/calculadora-alcohol-sangre-bac', 159);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-edad-gato-anos-humanos', 'Edad del gato en años humanos', 'Los gatos no envejecen 7 años por cada año humano — ese es un mito popular que persiste. La realidad felina es más rica: el primer año un gatito alcanza la pubertad (~15 años humanos), el segundo consolida la adultez joven (~24), y a partir del tercero suma ~4 años humanos por cada año gatuno.', 'mascotas', 'https://hacecuentas.com/calculadora-edad-gato-anos-humanos', 160);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-indice-bienestar-who5', 'Calculadora de bienestar subjetivo WHO-5 (OMS)', 'El WHO-5 es un cuestionario de 5 preguntas de la OMS para evaluar bienestar subjetivo de las últimas 2 semanas. Cada pregunta se puntúa de 0 a 5 y el total se multiplica por 4 para obtener un índice de 0 a 100. Puntajes mayores a 50 indican bienestar normal, entre 29 y 50 bienestar bajo, y menores a 28 sugieren…', 'vida', 'https://hacecuentas.com/calculadora-indice-bienestar-who5', 161);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-llegada-aeropuerto-minutos-vuelo', '¿A qué hora exacta llegar al aeropuerto?', 'Para llegar al aeropuerto a tiempo en 2026, restá del horario de despegue: 3 horas si es vuelo internacional, 2 horas si es doméstico. Sumá el tiempo de traslado desde casa según tráfico. Para un vuelo internacional a las 20:30 con 45 min de traslado: llegada al aeropuerto 17:30, salida de casa 16:45, gate cierra…', 'viajes', 'https://hacecuentas.com/calculadora-llegada-aeropuerto-minutos-vuelo', 162);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-pace-ritmo-running', 'Calculadora de pace (ritmo) de running', 'Para sacar tu pace de running, dividí los minutos del recorrido por los kilómetros: pace = tiempo (min) ÷ distancia (km). Si corriste 10 km en 50 minutos, tu pace es 5:00 min/km y la velocidad media 12 km/h. Para bajar de 2 horas en media maratón (21,1 km) necesitás un pace sostenido de 5:41 min/km. Sumá 5-10 segundos…', 'deportes', 'https://hacecuentas.com/calculadora-pace-ritmo-running', 163);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-talla-anillo-dedo', 'Calculadora de talla de anillo', 'Medí la circunferencia del dedo con un hilo. La talla AR/EU ≈ circunferencia en mm (ej: 56 mm = talla 56). La talla US se calcula: (circunferencia - 36.5) / 2.55.', 'salud', 'https://hacecuentas.com/calculadora-talla-anillo-dedo', 164);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-inflacion-poder-compra', 'Calculadora de Inflación y Poder de Compra', 'Con 30% de inflación anual, $100.000 de hoy valen $40.000 en 3 años. Si tu sueldo no sube al menos la inflación, estás perdiendo plata cada mes.', 'finanzas', 'https://hacecuentas.com/calculadora-inflacion-poder-compra', 165);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('conversor-dolar-argentina', 'Conversor de dólar Argentina', 'En Argentina no existe un solo dólar, existen varios: el oficial (minorista del BCRA), el blue (paralelo informal), el MEP (bolsa, vía bonos), el CCL (contado con liqui, liquidación en el exterior), el tarjeta (en 2026, igual al oficial para consumos directos en dólares; +30% sólo para turismo al exterior pagado en…', 'finanzas', 'https://hacecuentas.com/conversor-dolar-argentina', 166);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-love-calculator', 'Love Calculator — Calculadora del Amor', 'Love calculator: poné tu nombre y el de tu crush y descubrí el porcentaje de amor. El clásico test viral del amor. Probalo gratis.', 'vida', 'https://hacecuentas.com/calculadora-love-calculator', 167);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-precio-dolar-producto', 'Convertir Precio en Dólares a Pesos', 'Cada vez que ves un precio en dólares en Argentina, la pregunta inmediata es: ¿cuánto me sale realmente en pesos? La respuesta no es simple, porque en nuestro país existen múltiples tipos de cambio que pueden hacer que el mismo producto de US$100 cueste desde $105.000 hasta más de $170.000 dependiendo de cómo lo…', 'finanzas', 'https://hacecuentas.com/calculadora-precio-dolar-producto', 168);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-sueldo-hora-extra-nocturna-feriado', 'Calculadora de valor hora extra — nocturna y feriado', 'Las horas extra tienen recargos del 50% o 100% sobre el valor hora normal, y las horas nocturnas (21hs a 6hs) tienen un recargo adicional del 8 minutos por hora (equivalente a un 33% extra).', 'finanzas', 'https://hacecuentas.com/calculadora-sueldo-hora-extra-nocturna-feriado', 169);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-costo-por-kilometro-auto', 'Calculadora Costo por Kilómetro de Auto', 'Cuánto cobrar por kilómetro recorrido en Argentina 2026 depende del costo real del auto: ronda entre $150 y $500 por km. Para no perder plata, el valor a cobrar debería cubrir al menos nafta + desgaste ($200-350/km en un auto mediano); muchas empresas pagan entre $250 y $400 por km de viático. El costo total se…', 'automotor', 'https://hacecuentas.com/calculadora-costo-por-kilometro-auto', 170);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-creatinina-funcion-renal', 'Calculadora de Creatinina y Función Renal (eGFR)', 'La creatinina sérica es el marcador más usado de función renal: producto del metabolismo muscular filtrado exclusivamente por riñón. Valores normales 0.6–1.2 mg/dl en adultos, pero lo relevante es el eGFR (TFG estimada) calculada por fórmula CKD-EPI que considera edad, sexo y raza. TFG 90 normal, 60–89 leve, 30–59…', 'salud', 'https://hacecuentas.com/calculadora-creatinina-funcion-renal', 171);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-memoria-fotos-capacidad', 'Calculadora de Fotos que Entran en Tarjeta SD', 'Para saber cuántas fotos entran en tu tarjeta SD, dividí los GB por el tamaño promedio por foto: en una tarjeta de 128 GB con cámara de 24 MP caben aproximadamente 16.000 JPEG fino (8 MB cada uno), 5.120 RAW comprimidos (25 MB) o 2.666 RAW sin comprimir (48 MB). Para 4K H.264 entran ~365 minutos. Sumá 7% de overhead…', 'entretenimiento', 'https://hacecuentas.com/calculadora-memoria-fotos-capacidad', 172);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-ninera-hora-noche-fin-de-semana-tarifa', 'Tarifa niñera por hora (Argentina)', 'La tarifa hora de niñera en Argentina varía según día (semana vs fin de semana), horario (día vs noche), zona (CABA y zona norte vs interior) y cantidad de niños. La actividad está regulada por la Ley 26.844 de Personal de Casas Particulares que fija categorías y aportes obligatorios.', 'vida', 'https://hacecuentas.com/calculadora-ninera-hora-noche-fin-de-semana-tarifa', 173);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-nombre-bebe-significado', 'Buscador de significado de nombres de bebé', 'Elegir el nombre de tu bebé es una de las decisiones más emocionantes del embarazo. Esta herramienta te permite buscar el significado, origen y popularidad de miles de nombres en español, y te sugiere nombres similares si buscás inspiración.', 'salud', 'https://hacecuentas.com/calculadora-nombre-bebe-significado', 174);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-puntos-amex-membership-rewards', 'Puntos Amex Membership Rewards: valor y transferencias', 'Los puntos American Express Membership Rewards (MR) son una moneda flexible: podés transferirlos a aerolíneas (Aeroméxico, Delta, Avianca, Iberia, British Airways), usarlos en el portal Amex Travel, canjear por cashback o por productos. El valor varía enormemente según el uso: transferir a aerolíneas suele dar 1.5-2¢…', 'viajes', 'https://hacecuentas.com/calculadora-puntos-amex-membership-rewards', 175);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-asignacion-familiar-hijo-anses-tramo', 'Asignación familiar por hijo ANSES', 'La asignación familiar por hijo de ANSES se cobra por tramos según el Ingreso del Grupo Familiar (IGF): a mayor IGF, menor el monto. Desde junio 2026 va de $72.474 por hijo (Tramo A) a $15.257 (Tramo D), $0 sobre el tope; hijo con discapacidad cobra $120.000 sin tope de ingreso.', 'finanzas', 'https://hacecuentas.com/calculadora-asignacion-familiar-hijo-anses-tramo', 176);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-embargo-sueldo-porcentaje-maximo', 'Calculadora de embargo de sueldo — porcentaje máximo', 'Si tenés una deuda judicial, te pueden embargar parte del sueldo, pero hay límites legales. En Argentina, el artículo 147 de la LCT establece que solo se puede embargar el excedente del Salario Mínimo Vital y Móvil (SMVM), con topes del 10% al 20% según el monto.', 'finanzas', 'https://hacecuentas.com/calculadora-embargo-sueldo-porcentaje-maximo', 177);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-multa-transito-valor', 'Calculadora de Multas de Tránsito', '¿Te pusieron una multa de tránsito y querés saber cuánto vas a pagar? El valor de las multas varía según la infracción, la jurisdicción y la cantidad de unidades fijas (UF) que se aplican.', 'automotor', 'https://hacecuentas.com/calculadora-multa-transito-valor', 178);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-proporciones-receta', 'Calculadora de Proporciones de Receta', 'Para ajustar una receta, multiplicá cada ingrediente por el factor: porciones deseadas dividido porciones originales. Si una receta es para 4 y la querés para 6, el factor es 1,5. Las especias y la levadura no escalan lineal: usá 1,5× al duplicar, no 2×.', 'vida', 'https://hacecuentas.com/calculadora-proporciones-receta', 179);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-regla-de-tres-simple', 'Regla de tres simple', 'La regla de tres simple es probablemente la operación matemática más útil de la vida cotidiana — la usamos para calcular porcentajes, ajustar recetas de cocina, escalar presupuestos, convertir monedas, calcular tiempos de tareas y muchísimo más. Consiste en resolver una proporción cuando conocés 3 valores y falta el…', 'vida', 'https://hacecuentas.com/calculadora-regla-de-tres-simple', 180);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-bienes-personales-2026', 'Impuesto a los Bienes Personales 2026', 'Bienes Personales 2026 grava el patrimonio neto al 31/12 que excede el Mínimo No Imponible (~$350M) más la deducción casa habitación (hasta $450M). La escala Ley 27.743 va de 0.5% a 1.5%, unificada país y exterior. Adherentes al REIBP pagan 0.45% fijo hasta 2027.', 'finanzas', 'https://hacecuentas.com/calculadora-bienes-personales-2026', 181);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-energia-pc-gaming-costo-mes', 'Calculadora de Consumo Eléctrico PC Gaming', 'Una PC gaming consume entre 300 y 700W bajo carga y 80-120W en idle. Con 4 horas de juego diarias y tarifa de $120/kWh en Argentina 2026, un setup mid-range gasta unos 50 kWh/mes ($6.000) y uno high-end con RTX 4080 hasta $10.000/mes. La fórmula es: (watts × horas × 30) / 1000 × tarifa.', 'entretenimiento', 'https://hacecuentas.com/calculadora-energia-pc-gaming-costo-mes', 182);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-fecha-probable-parto-ultima-menstruacion', 'Calculadora de fecha probable de parto desde FUM (ciclo ajustable)', 'La regla de Naegele (Franz Naegele, 1812) es el método estándar mundial para estimar la fecha probable de parto (FPP): FPP = FUM + 280 días. Asume un ciclo menstrual regular de 28 días con ovulación al día 14.', 'salud', 'https://hacecuentas.com/calculadora-fecha-probable-parto-ultima-menstruacion', 183);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-indice-asistencia-faltas', 'Calculadora de Índice de Asistencia y Faltas', 'Con un mínimo del 75% de asistencia podés faltar al 25% de las clases: en una materia de 32 clases son hasta 8 faltas, en 20 clases son 5 faltas y en 16 clases, 4 faltas. El porcentaje se calcula como clases asistidas ÷ clases dictadas × 100. En universidades argentinas se exige 75% para la regularidad y 80% para…', 'educacion', 'https://hacecuentas.com/calculadora-indice-asistencia-faltas', 184);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-mcd-mcm-maximo-divisor-minimo-multiplo', 'MCD y MCM: Máximo Común Divisor y Mínimo Común Múltiplo', 'Estás sumando fracciones con distinto denominador y no sabés cuál es el mínimo común múltiplo. O querés repartir 48 facturas y 36 bolígrafos en la mayor cantidad posible de kits iguales sin que sobre nada. O simplemente tu hijo de primaria te pregunta cómo se calcula el MCD y te quedaste en blanco.', 'matematica', 'https://hacecuentas.com/calculadora-mcd-mcm-maximo-divisor-minimo-multiplo', 185);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-costo-medianera-muro-lindero', 'Calculadora de Costo de Medianera', 'El metro cuadrado de medianera de ladrillo hueco con encadenado, mano de obra y revoque cuesta entre 80.000 y 120.000 pesos en Argentina 2026. Una medianera estándar de 20 metros de largo por 3 metros de alto (60 m²) cuesta entre 4,8 y 7,8 millones de pesos. El vecino debe pagarte el 50% del costo total según el…', 'construccion', 'https://hacecuentas.com/calculadora-costo-medianera-muro-lindero', 186);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-monotributo-vs-responsable-inscripto', 'Monotributo vs. Responsable Inscripto: ¿Cuál me conviene?', 'Una de las decisiones fiscales más importantes que toma un trabajador independiente, profesional, comerciante o emprendedor argentino es la elección del régimen tributario: Monotributo (régimen simplificado, Ley 24.977) o Responsable Inscripto (régimen general: IVA + Ganancias + Autónomos + IIBB).', 'negocios', 'https://hacecuentas.com/calculadora-monotributo-vs-responsable-inscripto', 187);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-mortero-juntas-ladrillos-m2-pared', 'Calculadora de Mortero para Juntas de Ladrillos', 'Para calcular el mortero de juntas, multiplicá los m² de pared por el consumo según ladrillo: común con junta 1,5 cm necesita 14 kg de cemento + 0,04 m³ de arena por m²; hueco usa 9 kg de cemento + 0,025 m³ de arena por m². Dosificación estándar 1:3 (cemento:arena). Para una pared de 30 m² de ladrillo común: 420 kg de…', 'construccion', 'https://hacecuentas.com/calculadora-mortero-juntas-ladrillos-m2-pared', 188);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-mundial-2026-bonus-jugador-fase', 'Cuánto cobra un jugador en el Mundial 2026 — Bonus por fase y selección', 'En el Mundial 2026 un jugador campeón de Argentina cobra aprox USD 1,2 millones (FIFA paga USD 50 M al equipo, la AFA reparte ~65% entre 26 jugadores). Por solo pasar grupos: USD 170k bruto (~USD 50k neto tras impuestos). Cuartos de final: ~USD 500k. Subcampeón: ~USD 750k.', 'deportes', 'https://hacecuentas.com/calculadora-mundial-2026-bonus-jugador-fase', 189);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-porciones-torta-tamano-molde', 'Calculadora de porciones de torta según molde', 'Una torta redonda rinde porciones según el área del molde y la cantidad de capas. Molde de 20 cm con 2 capas da unas 14 porciones, 24 cm con 2 capas da 20 porciones y 28 cm con 2 capas rinde 27. Para adaptar recetas entre moldes multiplicá ingredientes por diámetro nuevo dividido el original al cuadrado. De 22 a 26 cm…', 'cocina', 'https://hacecuentas.com/calculadora-porciones-torta-tamano-molde', 190);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-ripte-actualizacion-jubilatoria-sueldo', 'RIPTE actualización jubilatoria', 'Para actualizar un sueldo por RIPTE multiplicá el sueldo histórico por el RIPTE del mes actual y dividí por el RIPTE del mes del sueldo histórico. El RIPTE (Remuneración Imponible Promedio de Trabajadores Estables) lo publica ANSES mensualmente con 2 meses de rezago. Se usa para reajustar haberes jubilatorios y…', 'finanzas', 'https://hacecuentas.com/calculadora-ripte-actualizacion-jubilatoria-sueldo', 191);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-salario-minimo-2026-comparativa', 'Salario mínimo vital y móvil 2026', 'El Salario Mínimo Vital y Móvil (SMVM) es el piso legal que ningún empleador puede pagar por debajo y se fija por consulta tripartita entre Estado, sindicatos y cámaras empresariales. En 2026 el SMVM se actualiza trimestralmente según la fórmula del Consejo del SMVM, con valores diferenciados por hora, día y mes.', 'finanzas', 'https://hacecuentas.com/calculadora-salario-minimo-2026-comparativa', 192);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-vo2max-test-cooper-12-minutos', 'Calculadora de VO2max — Test de Cooper', 'En 1968, el médico Kenneth Cooper publicó en JAMA un estudio que cambió la forma de medir la aptitud física sin laboratorio: el test de los 12 minutos.', 'deportes', 'https://hacecuentas.com/calculadora-vo2max-test-cooper-12-minutos', 193);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-ajuste-sueldo-inflacion', 'Calculadora: ¿Tu Sueldo le Ganó a la Inflación?', '¿Tu sueldo realmente subió o la inflación se lo comió? Ingresá tu sueldo anterior, tu sueldo actual y la inflación acumulada del período para saber si ganaste o perdiste poder adquisitivo. Te mostramos cuánto deberías ganar para mantener el mismo nivel de vida.', 'finanzas', 'https://hacecuentas.com/calculadora-ajuste-sueldo-inflacion', 194);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-autonomia-tanque-combustible', 'Calculadora Autonomía con Tanque de Combustible', 'Para calcular la autonomía con un tanque lleno, dividí la capacidad del tanque en litros por el consumo en litros cada 100 km y multiplicá por 100. Un auto mediano con tanque de 45 litros y consumo de 10 L/100km hace 450 km. Una pickup diésel con tanque de 80 litros y 10 L/100km hace 800 km. En ruta el consumo baja 30…', 'automotor', 'https://hacecuentas.com/calculadora-autonomia-tanque-combustible', 195);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-cuota-credito-hipotecario-uva-banco-nacion', 'Crédito hipotecario UVA: cuota', 'Ingresá monto crédito, plazo y TNA real y obtené cuota inicial al instante, con fórmula estándar del tema y referencias al pie. Resultado orientativo — para decisiones importantes consultá con un profesional.', 'finanzas', 'https://hacecuentas.com/calculadora-cuota-credito-hipotecario-uva-banco-nacion', 196);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-paritaria-comercio-2026-aumento-acumulado', 'Sueldo Comercio CCT 130/75 — Paritaria 2026', 'Con esta calculadora podés conocer tu sueldo bruto y neto según la escala salarial del CCT 130/75 (comercio) actualizada con la paritaria FAECYS 2026. Ingresá tu categoría, antigüedad y si recibís bonos no remunerativos para obtener el desglose completo.', 'finanzas', 'https://hacecuentas.com/calculadora-paritaria-comercio-2026-aumento-acumulado', 197);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-revoque-grueso-m3-m2', 'Arena/cemento para revoque grueso', 'La calculadora de arena y cemento para revoque grueso te permite estimar con precisión los materiales necesarios según la superficie a revocar y el espesor de la capa. El revoque grueso —también llamado "jaharro" o "fratasado grueso"— es la primera capa de mortero que se aplica sobre la mampostería cruda para nivelar…', 'construccion', 'https://hacecuentas.com/calculadora-revoque-grueso-m3-m2', 198);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-ventilacion-renovaciones-aire-hora', 'Calculadora de renovaciones de aire por hora', 'Las renovaciones de aire por hora se calculan multiplicando el volumen del ambiente (largo por ancho por alto en metros) por las RPH recomendadas según uso. Una cocina necesita 10 a 15 RPH, un baño 6 a 10 RPH y un dormitorio 2 a 4 RPH. Para un baño de 2 por 2 por 2,4 metros (9,6 m³) a 8 RPH el caudal es 77 m³/h, más…', 'construccion', 'https://hacecuentas.com/calculadora-ventilacion-renovaciones-aire-hora', 199);
INSERT OR REPLACE INTO mailing_pool (slug, title, answer_snippet, category, url, rank) VALUES ('calculadora-edad-metabolica', 'Calculadora de edad metabólica estimada', 'La edad metabólica compara tu tasa metabólica real con la esperada para tu edad cronológica. Se calcula usando la fórmula de Katch-McArdle (con masa magra) comparada con Mifflin-St Jeor. Si tu RMR real supera el RMR esperado, tu edad metabólica es menor que tu edad real.', 'salud', 'https://hacecuentas.com/calculadora-edad-metabolica', 200);
